import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Payment","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/payment.md","filePath":"03-developer/models/payment.md"}`),a={name:`03-developer/models/payment.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="payment" tabindex="-1">Payment <a class="header-anchor" href="#payment" aria-label="Permalink to “Payment”">​</a></h1><p>The <code>Payment</code> model stores information about payment requests and transactions associated with an invoice. An invoice can have multiple payments, such as an unsuccessful payment attempt followed by a retry, or payments made using different methods.</p><p>This model stores information such as the payment amount, method and status, gateway-related identifiers, and additional transaction details.</p><h2 id="payments-table-structure" tabindex="-1"><code>payments</code> table structure <a class="header-anchor" href="#payments-table-structure" aria-label="Permalink to “payments table structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Payment ID</td></tr><tr><td><code>invoice_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the associated invoice; related to the <code>invoices</code> table</td></tr><tr><td><code>amount</code></td><td>DECIMAL(20,2)</td><td>Yes</td><td>Payment amount</td></tr><tr><td><code>type</code></td><td>ENUM</td><td>Yes</td><td>Payment method; defaults to <code>ONLINE</code></td></tr><tr><td><code>status</code></td><td>ENUM</td><td>Yes</td><td>Payment status; defaults to <code>PENDING</code></td></tr><tr><td><code>order_id</code></td><td>VARCHAR(255)</td><td>No</td><td>Unique ID of the payment request or order</td></tr><tr><td><code>reference_id</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Transaction reference ID with the gateway or payment provider</td></tr><tr><td><code>comment</code></td><td>TEXT</td><td>Yes</td><td>Payment-related notes</td></tr><tr><td><code>meta</code></td><td>LONGTEXT</td><td>Yes</td><td>Additional payment information in JSON format</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Last update time</td></tr></tbody></table><h2 id="payment-methods" tabindex="-1">Payment methods <a class="header-anchor" href="#payment-methods" aria-label="Permalink to “Payment methods”">​</a></h2><p>The <code>type</code> field accepts the following values:</p><ul><li><code>ONLINE</code>: Online payment</li><li><code>CHEQUE</code>: Payment by check</li><li><code>CASH</code>: Cash payment</li><li><code>CARD</code>: Card payment</li><li><code>CASH_ON_DELIVERY</code>: Payment on delivery</li></ul><h2 id="payment-statuses" tabindex="-1">Payment statuses <a class="header-anchor" href="#payment-statuses" aria-label="Permalink to “Payment statuses”">​</a></h2><p>The <code>status</code> field accepts the following values:</p><ul><li><code>PENDING</code>: Payment awaiting resolution</li><li><code>SUCCESS</code>: Successful payment</li><li><code>FAIL</code>: Failed payment</li><li><code>CANCEL</code>: Canceled payment</li></ul><h2 id="payment-identifiers" tabindex="-1">Payment identifiers <a class="header-anchor" href="#payment-identifiers" aria-label="Permalink to “Payment identifiers”">​</a></h2><h3 id="order-id" tabindex="-1"><code>order_id</code> <a class="header-anchor" href="#order-id" aria-label="Permalink to “order_id”">​</a></h3><p>A unique identifier for the payment request or order. In <code>Invoice::storePaymentRequest()</code>, this value is received and stored through the <code>$orderId</code> parameter.</p><p>For credit payments, a value with the <code>CREDIT_</code> prefix and the current time is also generated. Therefore, this field is not necessarily the store order ID; it can be an internal identifier or one associated with the payment process.</p><p>The database enforces the uniqueness of <code>order_id</code>.</p><h3 id="reference-id" tabindex="-1"><code>reference_id</code> <a class="header-anchor" href="#reference-id" aria-label="Permalink to “reference_id”">​</a></h3><p>Stores the transaction reference ID. For example, in the PayPal implementation, after the payment is confirmed, the Capture ID is returned as <code>reference_id</code>.</p><p>This ID differs from <code>order_id</code>: the former refers to the completed transaction, while the latter is used to identify the payment request or order.</p><h3 id="comment" tabindex="-1"><code>comment</code> <a class="header-anchor" href="#comment" aria-label="Permalink to “comment”">​</a></h3><p>Stores text notes related to the payment. In <code>Invoice::storeFailPayment()</code>, the received error message is stored in this field. Other uses depend on the logic for each payment method.</p><h2 id="additional-information" tabindex="-1">Additional information <a class="header-anchor" href="#additional-information" aria-label="Permalink to “Additional information”">​</a></h2><h3 id="meta" tabindex="-1"><code>meta</code> <a class="header-anchor" href="#meta" aria-label="Permalink to “meta”">​</a></h3><p>Stores additional payment information in JSON format. In <code>Invoice::storePaymentRequest()</code>, this field contains information such as the request fingerprint, gateway name, token, IP, authenticated user ID, and User-Agent.</p><p>For successful payments, additional information such as <code>card_number</code> is also added to <code>meta</code>. In the PayPal example, the payer&#39;s email address is stored here instead of a card number.</p><p>The <code>meta</code> field is validated using the <code>CHECK (json_valid(meta))</code> constraint; therefore, any non-<code>NULL</code> value must be valid JSON.</p><h2 id="relationships-and-database-constraints" tabindex="-1">Relationships and database constraints <a class="header-anchor" href="#relationships-and-database-constraints" aria-label="Permalink to “Relationships and database constraints”">​</a></h2><ul><li>Every payment must be associated with an invoice.</li><li>The <code>invoice_id</code> relationship to the <code>invoices</code> table has <code>ON DELETE CASCADE</code>; deleting an invoice also deletes its dependent payments.</li><li><code>amount</code> is of type <code>BIGINT UNSIGNED</code>, so negative values and fractional amounts cannot be stored directly in this column.</li><li>Although the <code>type</code> and <code>status</code> fields have default values, they are nullable; therefore, the database also accepts <code>NULL</code>.</li></ul><h2 id="note-to-review" tabindex="-1">Note to review <a class="header-anchor" href="#note-to-review" aria-label="Permalink to “Note to review”">​</a></h2><p>The <code>amount</code> type differs from the amount fields in the <code>invoices</code> and <code>orders</code> tables. Before changing the column type, review the currency unit and how amounts are stored across all gateways; some gateways accept amounts in the smallest integer currency unit. The final decision should be based on the actual amount contract used by the application.</p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};